import {createRoot} from 'react-dom/client';
import {LayoutDashboard, Building2, Users, Layers, ArrowUpRight, ArrowDownToLine, Plus, Search, ChevronDown, ChevronLeft, ChevronRight, X, Check, CheckCircle2, AlertCircle, Clock3, MoreHorizontal, SlidersHorizontal, Upload, Download, FileSpreadsheet, ShieldCheck, LogOut, Menu, Pencil, Trash2, RotateCcw, History, Settings2, ArrowRight, Link2, Copy, Filter, Save, Euro} from 'lucide-react';
